import{_ as i,l as o,o as t,c as m,v as p,p as h,x as n,d as r,i as s,S as d,b as e}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"推理算力最优","description":"","frontmatter":{"title":"推理算力最优","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/inference-compute-optimal.md","filePath":"llm/inference-compute-optimal.md","lastUpdated":1789023840000}'),f={name:"llm/inference-compute-optimal.md"};function E(c,a,_,A,B,u){const l=o("Mermaid");return t(),m("div",null,[a[1]||(a[1]=p('<h1 id="推理算力最优" tabindex="-1">推理算力最优 <a class="header-anchor" href="#推理算力最优" aria-label="Permalink to &quot;推理算力最优&quot;">​</a></h1><div class="epigraph"><p>Chinchilla 的谷底最小化训练 FLOPs 上的损失；若部署要服务大量生成 token，过度训练一个较小的模型，往往比训练计算最优的大模型更便宜。</p><footer>—— Hoffmann et al., 2022 已区分训练最优与部署；Sardana 等, Beyond Chinchilla-Optimal: Accounting for Inference, 2024</footer></div><p><a href="/llm/emergence-debate">上一课</a>把「必须更大才有能力」降级为需检验的叙事。缺口是账本：主干 <a href="/llm/chinchilla">Chinchilla</a> 的谷底是 <strong>训练</strong> \\(C_{\\mathrm{train}}\\approx 6ND\\) 上最小化损失。一旦推理 token 数 \\(T_{\\mathrm{inf}}\\) 很大，总成本含 \\(C_{\\mathrm{inf}}\\propto N T_{\\mathrm{inf}}\\)（每生成 token 与参数量近线性）。Sardana 等人把推理写进目标，谷底移向更小 \\(N\\)、更大 \\(D\\)（过度训练）。本课写这本账，不重拟合 \\(\\alpha\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练最优：给定 \\(C_{\\mathrm{train}}\\)，选 \\(N,D\\) 使损失最低，大约 \\(D\\propto N\\)。部署最优：给定训练预算<strong>加上</strong>预期生成量，最小化损失或在固定损失下最小化总 FLOPs。大模型每 token 推理更贵。若你预期服务 \\(10^{12}\\) 生成 token，把预算从「再加宽 2×」挪到「同宽多训 4×」可能更优：训练更贵一点，推理便宜很多。Hoffmann 已经警告不要把训练最优当部署最优；Sardana 等人给出显式曲线。</p><p>这与涌现叙事冲突的点在于：产品若真需要某能力，应先看较小但过度训练的模型在连续度量上是否已够，而不是先跳到训练最优的更大 \\(N\\)。</p><p><span class="marginnote">推理成本还含 KV 缓存与批大小，不完全是 \\(N\\)。本课用 \\(N\\) 当一阶代理；服务课里的 paged attention 会改常数，不改「更小更久 vs 更大刚好训完」的方向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：</p><ol><li>训练 FLOPs \\(C_{\\mathrm{train}}(N,D)\\)。</li><li>预期生成 token \\(T_{\\mathrm{inf}}\\)（含失败重试与内部思维链）。</li><li>\\(C_{\\mathrm{inf}}\\approx \\kappa N T_{\\mathrm{inf}}\\)，\\(\\kappa\\) 含解码系数（小于训练的 6，因无反向，且解码阶段按生成长度计）。</li><li>在若干 \\((N,D)\\) 上用已拟合的 \\(L(N,D)\\) 估损失，画 \\(L\\) vs \\(C_{\\mathrm{train}}+C_{\\mathrm{inf}}\\)。</li></ol><p>\\(T_{\\mathrm{inf}}\\) 不确定时做敏感性：内部工具多、长 CoT，谷底更靠左（更小 \\(N\\)）。只做一次学术 benchmark 然后存档的模型，\\(T_{\\mathrm{inf}}\\approx 0\\)，回到 Chinchilla。</p><p>过度训练的极限受 <a href="/llm/multi-epoch-repetition">重复数据</a> 约束：没有足够 \\(U\\) 时，\\(D\\) 不能无限加。推理最优不能在数据墙之外假装成立。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>损失对 \\(N\\) 与 \\(D\\) 都递减但边际递减。推理成本对 \\(N\\) 近线性、对 \\(D\\) 在部署期为 0。于是最优点满足：再加一点 \\(N\\) 带来的损失下降，刚好被未来所有生成 token 的额外费用抵消。\\(T_{\\mathrm{inf}}\\) 越大，抵消越早，\\(N\\) 越小。蒸馏、量化、投机解码降低 \\(\\kappa\\)，会把谷底往回推向更大 \\(N\\)——它们与过度训练是替代关系，应进同一张账，不要分开吹。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 MoE 的「稀疏 \\(N\\)、密 FLOPs」算完，稠密升级课会碰到：推理期若只激活部分专家，\\(\\kappa\\) 变。也不处理延迟 SLA：有时必须更大模型换更短 CoT，总 FLOPs 不是唯一目标。</p><p>内部思维链把 \\(T_{\\mathrm{inf}}\\) 放大数倍时，应重新跑敏感性，而不是沿用「普通聊天」的谷底。下一课：无论最优在哪，超参与形状决策应先在小代理上做——但代理必须能复现大模型的不稳与数据制度。</p>',17)),(t(),h(d,null,{default:n(()=>[s(l,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20CT%5B%22%E8%AE%AD%E7%BB%83%20FLOPs%22%5D%20--%3E%20SUM%5B%22%E6%80%BB%E8%AE%A1%E7%AE%97%22%5D%0A%20%20INF%5B%22%E6%8E%A8%E7%90%86%3A%20%E4%B8%8E%20N%20%E5%92%8C%E7%94%9F%E6%88%90%E9%87%8F%22%5D%20--%3E%20SUM%0A%20%20SUM%20--%3E%20OPT%5B%22%E8%B0%B7%E5%BA%95%3A%20%E6%9B%B4%E5%B0%8F%20N%E3%80%81%E6%9B%B4%E5%A4%A7%20D%22%5D%0A%20%20CH%5B%22%E7%BA%AF%E8%AE%AD%E7%BB%83%E6%9C%80%E4%BC%98%22%5D%20--%3E%20BIGGER%5B%22%E6%9B%B4%E5%A4%A7%20N%E3%80%81%E5%88%9A%E5%A5%BD%E8%AE%AD%E5%AE%8C%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"训练计算最优最小化 \\(C_{\\mathrm{train}}\\) 上的损失；计入推理后谷底移向过度训练的较小模型。"),e("li",null,"\\(T_{\\mathrm{inf}}\\) 与长 CoT 把谷底进一步推左；仅存档评测则回到 Chinchilla。"),e("li",null,"数据墙 \\(f(R)\\) 限制过度训练；量化与稀疏与「更小更久」是替代。"),e("li",null,"不要用涌现规模故事覆盖这本账。"),e("li",null,"出处：Hoffmann et al., 2022；Sardana 等, 2024。")],-1))])}const D=i(f,[["render",E]]);export{C as __pageData,D as default};
